rule keyword "Credential stuffing attack" {
  meta:
    author = "Your Name"
  description = "Detects credential stuffing attacks"
  reference = "https://example.com"
  tags = "credential_compromise, lateral_movement"

  condition:
    any of
      {
        NetworkConnection from any to IP addr == 10.0.5.14
        NetworkConnection from any to IP addr == 10.0.8.200
